quiz.answer:
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
)

type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
	Age  int    `json:"age"`
}

func main() {
	users := []User{}
	sc := bufio.NewScanner(os.Stdin)
	for sc.Scan() {
		var u User
		if _, err := fmt.Sscan(sc.Text(), &u.Name, &u.Age); err != nil {
			continue
		}
		u.ID = len(users) + 1
		users = append(users, u)
	}
	b, err := json.Marshal(users)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println(string(b))
}

