package main

import (
	"errors"
	"fmt"
	"log"
	"strings"
)

// ---- ここから下は「DB の代わり」。変えなくてよい ----

type Store struct {
	dsn    string
	tables []string
}

func openStore(dsn string) (*Store, error) {
	if dsn == "" {
		return nil, errors.New("empty dsn")
	}
	return &Store{dsn: dsn}, nil
}

func (s *Store) Exec(query string) error {
	s.tables = append(s.tables, strings.TrimPrefix(query, "CREATE TABLE IF NOT EXISTS "))
	return nil
}

// ---- ここまで ----

var db *Store

func initDB() {
	var err error
	db, err = openStore("host=localhost dbname=testdb")
	if err != nil {
		log.Fatal(err)
	}
	if err = db.Exec("CREATE TABLE IF NOT EXISTS users"); err != nil {
		log.Fatal(err)
	}
	fmt.Println("Database connected and table created")
}

func main() {
	initDB()
	if db == nil {
		fmt.Println("db is nil")
		return
	}
	fmt.Println("dsn:", db.dsn)
	fmt.Println("tables:", strings.Join(db.tables, ","))
}

quiz.explanation:
`db, err := openStore(...)` の `:=` は、関数の中に新しいローカル変数 db を作ります。接続はローカルの db に入り、グローバルの db は nil のまま残ります。直し方は、先に `var err error` で err だけを宣言し、`db, err = openStore(...)` と `=` で代入することです。

```go
func initDB() {
	var err error
	db, err = openStore("host=localhost dbname=testdb")
	if err != nil {
		log.Fatal(err)
	}
	...
}
```

`var db *Store` を initDB の中に書き足すのも誤りです。それもローカル変数になるので、結果は同じく `db is nil` です。
